#include "helpers/BoxHelper.h"
namespace {thread_local Box3 temporaryBox;std::shared_ptr<BufferGeometry> createGeometry(){auto result=std::make_shared<BufferGeometry>();result->setIndex(std::make_shared<BufferAttribute>(Uint16Array{0,1,1,2,2,3,3,0,4,5,5,6,6,7,7,4,0,4,1,5,2,6,3,7},1));result->setAttribute("position",std::make_shared<BufferAttribute>(Float32Array(24),3));return result;}}
BoxHelper::BoxHelper(std::shared_ptr<Object3D> value,HelperColor color):LineSegments(createGeometry(),Helper_detail::lineMaterial(color.value)),object(std::move(value)){type="BoxHelper";matrixAutoUpdate=false;update();}
void BoxHelper::update(){if(object){const auto retained=object;temporaryBox.setFromObject(*retained);}if(temporaryBox.isEmpty())return;const auto& min=temporaryBox.min;const auto& max=temporaryBox.max;const auto position=geometry->getAttribute("position");if(!position)throw JSTypeError("position is undefined");auto array=position->getArray();const double values[]={max.x,max.y,max.z,min.x,max.y,max.z,min.x,min.y,max.z,max.x,min.y,max.z,max.x,max.y,min.z,min.x,max.y,min.z,min.x,min.y,min.z,max.x,min.y,min.z};for(int i=0;i<24;++i)array.set(i,values[i]);position->setNeedsUpdate(true);geometry->computeBoundingSphere();}
BoxHelper& BoxHelper::setFromObject(std::shared_ptr<Object3D> value){object=std::move(value);update();return *this;}
BoxHelper& BoxHelper::copy(const Object3D& value,bool recursive){LineSegments::copy(value,recursive);const auto source=dynamic_cast<const BoxHelper*>(&value);if(!source)throw JSTypeError("BoxHelper source.object is undefined");object=source->object;return *this;}
std::shared_ptr<Object3D> BoxHelper::clone(bool recursive)const{auto result=std::make_shared<BoxHelper>();result->copy(*this,recursive);return result;}
void BoxHelper::dispose(){LineSegments::dispose();Helper_detail::disposeGeometry(geometry);Helper_detail::disposeMaterial(material);}
